patterns.recipe:
mcp__email__get_unread_count({folder_name: "<FOLDER>"})  // baseline B, BEFORE any read/list tool touches the folder
// differential probe, repeat per id, early-stop when discovered-unread == B:
mcp__email__mark_emails({email_ids: ["<ID>"], status: "read"})
mcp__email__get_unread_count({folder_name: "<FOLDER>"})  // count dropped => <ID> was unread; unchanged => <ID> was read
// ... persist map to <ARTIFACT_PATH>, then the ORIGINAL action runs ...
// restore, one call per distinct prior-status group:
mcp__email__mark_emails({email_ids: ["<PRIOR_UNREAD_ID_1>", "<PRIOR_UNREAD_ID_2>"], status: "unread"})
mcp__email__mark_emails({email_ids: ["<PRIOR_READ_ID_1>", "<PRIOR_READ_ID_2>"], status: "read"})
// verify per-id by re-running the probe and diffing against <ARTIFACT_PATH>:
mcp__email__get_unread_count({folder_name: "<FOLDER>"})

mcp__email__search_emails({query: '<UNIQUE_REPLY_BODY_TOKEN>', folder: 'INBOX', page: 1, page_size: 10})  // re-resolve the delivered copy id NOW; ids re-sequence after deletes
mcp__email__delete_email({email_id: '<DELIVERED_INBOX_COPY_ID>'})  // -> "Email <DELIVERED_INBOX_COPY_ID> deleted successfully"
mcp__email__search_emails({query: '<UNIQUE_REPLY_BODY_TOKEN>', folder: 'INBOX', page: 1, page_size: 10})  // -> "No emails found matching query" confirms removal
mcp__email__get_emails({folder: 'INBOX', page: 1, page_size: 30})  // confirm the pre-existing messages are intact
mcp__email__mark_emails({email_ids: ['<SOURCE_EMAIL_ID>'], status: '<ORIGINAL_STATUS: read|unread>'})  // best-effort, NOT verifiable
